def divide(a, b):
    if b == 0:
        return 0, ValueError("division by zero")
    return a / b, None

result, err = divide(10, 0)
if err:
    print("Error:", err)

class NotFoundError(Exception):
    def __init__(self, key):
        self.key = key
        super().__init__(f"not found: {key}")

def find_user(name):
    if name != "alice":
        raise NotFoundError(name)

try:
    find_user("bob")
except NotFoundError:
    print("User not found")

class ValidationError(Exception):
    def __init__(self, field, msg):
        self.field = field
        super().__init__(msg)

def validate():
    raise ValidationError("email", "invalid email")

try:
    validate()
except ValidationError as ve:
    print(ve.field)

def safe_divide(a, b):
    if b == 0:
        return None, ValueError('cannot divide by zero')
    return a // b, None

result, err = safe_divide(10, 2)
if err:
    print('Error:', err)
else:
    print(result)

ERR_NOT_FOUND = ValueError("not found")

def get_item(i):
    if i < 0:
        return ERR_NOT_FOUND
    return "item"

err = get_item(-1)
if err is ERR_NOT_FOUND:
    print("not found")
